cat > src/lib/email.ts <<'EOF'
// Transactional email via Resend's REST API (https://resend.com/docs/api-reference/emails/send-email).
// Plain fetch, so no extra dependency. Without RESEND_API_KEY (local dev) emails are logged instead.

export type Email = {
  to: string;
  subject: string;
  html: string;
  text: string;
};

const FROM = process.env.EMAIL_FROM ?? "Notely <onboarding@resend.dev>";
const APP_URL = process.env.APP_URL ?? "http://localhost:3000";

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export async function sendEmail(email: Email): Promise<void> {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) {
    console.log(`[email:dev] to=${email.to} subject="${email.subject}"\n${email.text}`);
    return;
  }

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ from: FROM, ...email, to: [email.to] }),
  });
  if (!res.ok) {
    throw new Error(`Email send failed (${res.status}): ${await res.text()}`);
  }
}

export function welcomeEmail(user: { email: string; name: string }): Email {
  const url = `${APP_URL}/dashboard`;
  return {
    to: user.email,
    subject: "Welcome to Notely",
    text: `Hi ${user.name},\n\nWelcome to Notely! Get started here: ${url}\n`,
    html: `<p>Hi ${escapeHtml(user.name)},</p><p>Welcome to Notely! <a href="${url}">Open your dashboard</a>.</p>`,
  };
}

export function passwordResetEmail(
  user: { email: string; name: string },
  token: string,
  ttlMinutes: number,
): Email {
  const url = `${APP_URL}/reset-password?token=${encodeURIComponent(token)}`;
  return {
    to: user.email,
    subject: "Reset your Notely password",
    text: `Hi ${user.name},\n\nReset your password (link valid for ${ttlMinutes} minutes): ${url}\n\nIf you didn't request this, ignore this email.\n`,
    html: `<p>Hi ${escapeHtml(user.name)},</p><p><a href="${url}">Reset your password</a>. The link is valid for ${ttlMinutes} minutes.</p><p>If you didn't request this, ignore this email.</p>`,
  };
}
EOF
cat > .env.example <<'EOF'
# Resend (https://resend.com) API key. Leave empty in local dev to log emails to the console instead.
RESEND_API_KEY=re_xxxxxxxxxxxxxxxxxxxxxxxx
# Sender; must be on a domain verified in Resend.
EMAIL_FROM="Notely <no-reply@example.com>"
# Public base URL used in email links.
APP_URL=http://localhost:3000
EOF
printf '!.env.example\n' >> .gitignore
python3 - <<'EOF'
p='src/lib/users.ts'
s=open(p).read()
s='''import { createHash, randomBytes } from "node:crypto";
import { passwordResetEmail, sendEmail, welcomeEmail } from "./email";

'''+s
s+='''
export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // A failed welcome email must not fail signup.
  try {
    await sendEmail(welcomeEmail(user));
  } catch (err) {
    console.error("Welcome email failed", err);
  }
  return user;
}

const RESET_TTL_MINUTES = 60;
// Only a hash of each token is stored, so a leaked store can't be used to reset passwords.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

// Always resolves the same way whether or not the email exists, to avoid account enumeration.
export async function requestPasswordReset(email: string): Promise<void> {
  const normalized = email.trim().toLowerCase();
  const user = users.find((u) => u.email === normalized);
  if (!user) return;

  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), {
    userId: user.id,
    expiresAt: Date.now() + RESET_TTL_MINUTES * 60_000,
  });
  await sendEmail(passwordResetEmail(user, token, RESET_TTL_MINUTES));
}

// Single-use. Returns the user the token belongs to, or undefined if invalid/expired.
// TODO: the caller must set the new password once credentials exist.
export async function consumePasswordResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
'''
open(p,'w').write(s)
EOF
npx tsc --noEmit && npm run lint 2>&1 | tail -5; git status --short

